 let((mut parent,mut source),heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||{let(cancel,_)=semio_framework_job::CancelToken::admit_root(stock).unwrap().unwrap();let(authority,_)=JobPayloadAuthority::admit(OperationId(807),Generation(3),stock).unwrap().unwrap();let(parent,_)=OriginalCallerSourceParent::admit(authority,cancel,stock).ok().unwrap();(parent,Some(Err(MediaError::Payload("original港".into(),"same original output 源".into()))))});let(mut born,mut released)=(heap.requested_bytes,heap.released_bytes);let mut sequence=0;let mut recipient=Default::default();let mut cx=parent.borrow_context(StepBudget::new(32768,1500,stock),now_us,&mut sequence,&mut recipient).unwrap();let identity=cx.original_recipient_identity();let mut completion=None;let before=cx.retained_progress();let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||ArtifactMediaExportCompletion::original_birth_admit(&mut completion,&mut cx));assert!(result.unwrap());let after=cx.retained_progress();assert_eq!((heap.requested_bytes,heap.released_bytes),(after.retained_capacity_bytes-before.retained_capacity_bytes,after.released_bytes-before.released_bytes));born+=heap.requested_bytes;released+=heap.released_bytes;let completion=completion.unwrap();let mut published=false;
 let pointer=match source.as_ref().unwrap(){Err(MediaError::Payload(_,message))=>message.as_ptr(),_=>unreachable!()};
 for grant in [RetainedCloneGrant{maximum_items:0,..stock},RetainedCloneGrant{maximum_copy_bytes:0,..stock}]{let before=cx.retained_progress();let fuel=cx.fuel_remaining();let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||cx.with_retained_loan(grant,|same|completion.complete_original(&mut source,&mut published,same)));assert!(!result.unwrap());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(cx.retained_progress(),before);assert_eq!(cx.fuel_remaining(),fuel);assert!(!published);assert!(matches!(source.as_ref(),Some(Err(MediaError::Payload(_,message)))if message.as_ptr()==pointer));}
 {let borrowed=completion.inner.state.try_lock().unwrap();let before=cx.retained_progress();let fuel=cx.fuel_remaining();let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||completion.complete_original(&mut source,&mut published,&mut cx));assert!(!result.unwrap());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(cx.retained_progress(),before);assert_eq!(cx.fuel_remaining(),fuel);drop(borrowed)}
 let before=cx.retained_progress();let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||completion.complete_original(&mut source,&mut published,&mut cx));assert!(result.unwrap());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(cx.retained_progress().copied_bytes-before.copied_bytes,size_of::<Result<ArtifactMediaExportResult,MediaError>>()+size_of::<bool>());assert!(source.is_none()&&published);assert!(matches!(completion.inner.state.try_lock().unwrap().value.as_ref(),Some(Err(MediaError::Payload(_,message)))if message.as_ptr()==pointer));
